module top;
  integer i0, i1, i2, i3, sel, r;
  initial begin
    r = $fscanf(32'h8000_0000, "%d %d %d %d %d", i0, i1, i2, i3, sel);
    while (r == 5) begin
      case (sel)
        0: $display("%0d", i0);
        1: $display("%0d", i1);
        2: $display("%0d", i2);
        3: $display("%0d", i3);
        default: $display("x");
      endcase
      r = $fscanf(32'h8000_0000, "%d %d %d %d %d", i0, i1, i2, i3, sel);
    end
    $finish;
  end
endmodule
